const appScreen=document.getElementById('screen');
const films=[{name:'海岸线之外',en:'BEYOND\nTHE COAST',art:'coast',folder:'海岸',time:'18:24',meta:'2025 · 旅行影像'},{name:'山野之间',en:'INTO\nTHE STILL',art:'alpine',folder:'山野',time:'24:08',meta:'2025 · 自然纪录'},{name:'北境的清晨',en:'NORTHERN\nLIGHT',art:'coast',folder:'海岸',time:'12:36',meta:'2024 · 旅行影像'},{name:'湖畔的时间',en:'SLOW\nMORNINGS',art:'alpine',folder:'山野',time:'32:10',meta:'2024 · 自然纪录'}];
let state={scene:'library',folder:'旅行与自然',scope:'all',random:false,quality:'自动',index:0,saved:new Set(),paused:false,tablet:false,query:'',queue:[0,1,2,3],queuePos:0};
const descriptions={library:['01 / LIBRARY','每次打开，<br>都有想看的。','继续观看与固定目录，构成片库的第一层。连接状态收进轻量标签，内容拥有最多空间。'],browse:['02 / SCOPE','从一个目录，<br>进入一段旅程。','文件夹入口和视频平铺共存。包含子目录的范围始终可见，顺序与随机播放共享同一组内容。'],player:['03 / CINEMA','让界面退后，<br>让画面向前。','单指左右切片，双指缩放。画质、旋转与播放顺序随手可达；横屏后仍遵循同一套交互。'],connect:['04 / CONNECT','私人影院，<br>从连接开始。','先选择服务，再填写必要信息。连接异常给出明确修复路径，首次体验也可直接使用演示片库。'],pro:['05 / PRO','为常用的能力，<br>付一次费。','基础播放完整开放。离线、多来源和智能片单成为 Pro 的核心价值，付费入口只在主动需要时出现。'],saved:['06 / COLLECTION','把喜欢的，<br>留在手边。','视频与目录都能收藏。整理服务于下一次观看，不增加日常维护负担。'],offline:['07 / OFFLINE','离开网络，<br>也能继续。','下载队列清晰展示进度与存储预算；明确提醒离线文件属于当前设备。']};
function nav(active='library'){return `<nav class="tabbar" aria-label="应用导航">${[['library','◫','片库'],['saved','♡','收藏'],['offline','↓','离线'],['settings','⚙','设置']].map(([id,icon,label])=>`<button data-scene="${id}" class="${active===id?'active':''}"><span>${icon}</span>${label}</button>`).join('')}</nav>`}
function appTop(title){return `<div class="topbar"><span class="wordmark">${title}</span><button class="round" data-scene="connect" aria-label="添加来源">＋</button></div>`}
function available(){return films.map((f,i)=>i).filter(i=>(state.folder==='旅行与自然'?state.scope==='all':films[i].folder===state.folder)&&films[i].name.includes(state.query))}
function posters(ids){return `<div class="posters">${ids.map(i=>{let f=films[i];return `<button class="poster" data-play="${i}"><div class="cover" style="background-image:url('assets/${f.art}.png');background-position:${i>1?'70%':'45%'} center"><span class="cover-title">${f.en.replace('\n','<br>')}</span><span class="duration">${f.time}</span></div><strong>${f.name}</strong><small>${f.meta}</small></button>`}).join('')}</div>`}
function library(){return `<div class="scroll">${appTop('glide')}<div class="title-row"><h2>你的片库</h2><button class="badge online" data-scene="connect">家里的 Jellyfin</button></div><div class="sub">好内容，值得一看再看。</div><button class="hero" style="width:100%;text-align:left" data-play="0"><div class="hero-content"><div class="eyebrow">CONTINUE WATCHING</div><div class="hero-row"><div><h3>海岸线之外</h3><div class="sub" style="color:#ddd">旅行与自然 · 还剩 12 分钟</div></div><span class="play-round" style="display:grid;place-items:center">▶</span></div><div class="progress"><span></span></div></div></button><div class="section-head"><h3>媒体库</h3><span class="sub">2 个媒体库</span></div><div class="library-tiles"><button class="tile" data-folder="旅行与自然"><span class="glyph">▱</span><strong>旅行与自然</strong><small>4 部视频 · 2 个目录</small></button><button class="tile" data-action="family"><span class="glyph">▱</span><strong>家庭时光</strong><small>尚未添加视频</small></button></div><div class="section-head"><h3>最近加入</h3><button data-folder="旅行与自然">查看全部 ↗</button></div>${posters([1,2])}</div>${nav()}`}
function browse(){let ids=available();return `<div class="scroll"><div class="bread"><button data-scene="library">‹ 片库</button><span>/</span><button data-folder="旅行与自然">旅行与自然</button>${state.folder!=='旅行与自然'?'<span>/ '+state.folder+'</span>':''}</div><div class="title-row"><h2>${state.folder}</h2><button class="round" data-action="pin" aria-label="固定此目录">⌑</button></div><div class="sub">${ids.length} 部视频 · 家里的 Jellyfin</div>${state.folder==='旅行与自然'?`<div class="folder-row"><button class="folder-chip" data-folder="海岸"><span>▱</span>海岸 <small>2</small></button><button class="folder-chip" data-folder="山野"><span>▱</span>山野 <small>2</small></button></div>`:'<div style="height:15px"></div>'}<input class="search" aria-label="搜索当前范围" placeholder="⌕  搜索当前范围的视频" value="${state.query.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}"><div class="section-head"><h3>全部视频</h3><select class="scope" aria-label="视频范围"><option value="all" ${state.scope==='all'?'selected':''}>含子目录</option><option value="direct" ${state.scope==='direct'?'selected':''}>仅当前层</option></select></div><div class="toolbar"><div class="toggle"><button data-order="seq" class="${!state.random?'active':''}">顺序播放</button><button data-order="random" class="${state.random?'active':''}">随机播放</button></div><button class="primary" data-action="start">▶ 刷本目录</button></div><div id="results">${ids.length?posters(ids):'<div class="notice">当前范围没有视频。试试“含子目录”，或更换搜索词。</div>'}</div></div>${nav()}`}
function player(){let f=films[state.index];return `<div class="player"><div class="player-top"><button data-scene="browse" aria-label="返回目录">⌄</button><span>${state.folder} · ${state.queuePos+1} / ${state.queue.length}</span><button data-action="quality" aria-label="播放设置">•••</button></div><div class="player-visual fit" style="background-image:url('assets/${f.art}.png')" aria-label="影片画面，可左右拖动换片"></div><div class="player-meta"><div class="eyebrow">${f.meta}</div><h2>${f.name}</h2><div class="sub">${state.random?'随机播放':'顺序播放'} · ${state.quality==='自动'?'自动 · 原画直放':state.quality}</div></div><div class="player-controls"><div class="time"><span id="elapsed">06:12</span><span>${f.time}</span></div><input type="range" min="0" max="100" value="34" aria-label="播放进度"><div class="transport"><button data-action="save" aria-label="收藏当前视频">${state.saved.has(state.index)?'♥':'♡'}</button><button data-action="prev" aria-label="上一个视频">‹</button><button class="pause" data-action="pause" aria-label="播放或暂停">${state.paused?'▶':'Ⅱ'}</button><button data-action="next" aria-label="下一个视频">›</button><button data-action="rotate" aria-label="横屏预览">⛶</button></div><div class="player-bottom"><button data-action="quality">${state.quality} ⌃</button><button data-action="fit">适应画面</button><button data-action="queue">${state.random?'随机':'顺序'} ⇄</button></div></div></div>`}
function connect(){return `<div class="scroll"><div class="bread"><button data-scene="library">‹ 返回片库</button></div><div class="connection-icon">◈</div><h2>连接你的私人影院</h2><p class="sub">视频留在你的服务器，精彩随身。</p><div class="toggle"><button class="active" data-action="jelly">Jellyfin</button><button data-action="dav">WebDAV</button></div><form class="form" id="connect-form"><label for="server">服务器地址</label><input id="server" type="url" placeholder="https://media.example.com" required><label for="user">用户名</label><input id="user" autocomplete="off" placeholder="你的用户名" required><label for="pass">密码</label><input id="pass" type="password" autocomplete="off" placeholder="服务器密码" required><button class="primary wide" type="submit">连接并选择媒体库 →</button></form><div class="notice">设计演示，请使用任意虚构信息。填写内容不会发送，也不会保存。</div><button class="sub" data-folder="旅行与自然">先体验演示片库 ↗</button></div>`}
function pro(){return `<div class="scroll"><div class="topbar"><button data-scene="library" class="round" aria-label="关闭Pro页面">×</button><button class="sub" data-action="restore">恢复购买</button></div><div class="pro-title">glide <i>pro.</i></div><h2>更多自由，随身携带。</h2><p class="sub">为认真收藏、随心观看的你。</p><div class="pro-art"></div>${[['↓','离线，也有好内容','下载到设备，旅途中接着看'],['◫','所有来源，一个片库','连接更多服务器，自由切换'],['⌑','让收藏更懂你','智能片单与专属播放偏好']].map(x=>`<div class="feature"><span>${x[0]}</span><div>${x[1]}<small>${x[2]}</small></div></div>`).join('')}<div class="price"><div>Pro 永久版<small style="display:block">一次购买 · 无自动续费</small></div><strong>¥98</strong></div><button class="primary wide" data-action="purchase">解锁 Glide Pro</button><p class="sub" style="text-align:center">设计占位价 · 尚未开放购买</p><p class="sub" style="text-align:center">基础播放始终免费 · 无广告</p></div>`}
function saved(){let ids=[...state.saved];return `<div class="scroll">${appTop('收藏')}<h2>留给下一次心动。</h2><p class="sub">收藏的视频，随时回来看。</p>${ids.length?posters(ids):'<div class="notice">还没有收藏的视频。播放时点亮爱心，即可留在这里。</div>'}<div class="section-head"><h3>固定目录</h3></div><button class="tile" data-folder="旅行与自然">▱ 旅行与自然 <small>4 部视频</small></button></div>${nav('saved')}`}
function offline(){return `<div class="scroll">${appTop('离线')}<div class="connection-icon">↓</div><h2>把喜欢的，带在身边。</h2><p class="sub">在视频详情中加入下载，即可离线观看。</p><div class="notice">当前没有离线视频。离线下载是规划中的 Pro 能力。</div><button class="primary wide" data-scene="pro">了解 Glide Pro →</button></div>${nav('offline')}`}
function render(){document.getElementById('device-frame').classList.toggle('cinema',state.scene==='player');let actual=state.scene==='settings'?'settings':state.scene;appScreen.innerHTML=actual==='settings'?`<div class="scroll">${appTop('设置')}<h2>你的观看方式。</h2><button class="choice" data-scene="connect">来源管理 <span>›</span></button><button class="choice" data-action="quality">播放与画质 <span>›</span></button><button class="choice" data-scene="pro">Glide Pro <span>›</span></button><div class="notice">设计原型版本 01<br>隐私：不采集输入，不连接真实服务。</div></div>${nav('settings')}`:({library,browse,player,connect,pro,saved,offline}[actual]||library)();let d=descriptions[actual]||descriptions.library;document.getElementById('note-number').textContent=d[0];document.getElementById('note-title').innerHTML=d[1];document.getElementById('note-copy').textContent=d[2];document.querySelectorAll('.scenes [data-scene]').forEach(b=>b.classList.toggle('selected',b.dataset.scene===actual));bindLocal()}
function toast(t){appScreen.querySelector('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=t;appScreen.append(e);setTimeout(()=>e.remove(),3300)}
function quality(){let el=document.createElement('div');el.className='sheet-scrim';el.innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-label="画质选择"><div class="handle"></div><div class="sheet-head"><h3>播放画质</h3><button data-action="close" aria-label="关闭设置">×</button></div>${[['自动','根据连接选择合适画质'],['原画','原始清晰度 · 需要更好的网络'],['1080p','最高1080p · 由 Jellyfin 转码']].map(([v,t])=>`<button class="choice ${state.quality===v?'selected':''}" data-quality="${v}"><span>${v}<small>${t}</small></span><span>${state.quality===v?'✓':''}</span></button>`).join('')}<p class="sub">切换保留观看进度。原型仅演示选择状态。</p></section>`;appScreen.append(el);el.querySelector('button').focus()}
function start(i){let ids=state.scene==='saved'?[...state.saved]:available();if(!ids.includes(i))ids=films.map((_,j)=>j);if(state.random){ids=ids.filter(j=>j!==i);for(let n=ids.length-1;n>0;n--){let k=Math.floor(Math.random()*(n+1));[ids[n],ids[k]]=[ids[k],ids[n]]}ids.unshift(i)}state.queue=ids;state.queuePos=ids.indexOf(i);state.index=i;state.paused=false;state.scene='player';render()}
function next(delta){let n=state.queuePos+delta;if(n<0||n>=state.queue.length){toast(delta>0?'已到当前范围最后一部':'已到当前范围第一部');return}state.queuePos=n;state.index=state.queue[n];render()}
function device(){state.tablet=!state.tablet;document.getElementById('device-frame').classList.toggle('tablet',state.tablet);document.querySelector('.stage').classList.toggle('tablet-stage',state.tablet);document.getElementById('device').textContent=state.tablet?'iPhone 视图 ↗':'iPad 视图 ↗'}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='device'){device();return}if(b.dataset.scene){state.scene=b.dataset.scene;render();return}if(b.dataset.folder){state.folder=b.dataset.folder;state.scope='all';state.query='';state.scene='browse';render();return}if(b.dataset.play!==undefined){start(Number(b.dataset.play));return}if(b.dataset.order){state.random=b.dataset.order==='random';render();return}if(b.dataset.quality){state.quality=b.dataset.quality;render();toast('已选择 '+state.quality+' · 演示状态');return}switch(b.dataset.action){case'quality':quality();break;case'close':appScreen.querySelector('.sheet-scrim')?.remove();break;case'pause':state.paused=!state.paused;render();break;case'next':next(1);break;case'prev':next(-1);break;case'save':state.saved.has(state.index)?state.saved.delete(state.index):state.saved.add(state.index);render();break;case'rotate':device();break;case'fit':appScreen.querySelector('.player-visual').classList.toggle('fit');break;case'queue':state.random=!state.random;start(state.index);break;case'start':if(available().length)start(available()[0]);else toast('当前范围没有可播放的视频');break;case'pin':toast('已固定“'+state.folder+'” · 演示状态');break;case'family':toast('家庭时光还没有视频，可先浏览旅行与自然');break;case'purchase':toast('这是购买页设计预览，不会扣款');break;case'restore':toast('正式版将通过 App Store 恢复购买');break;case'dav':toast('WebDAV 使用相同表单；正式版支持协议切换');break;case'jelly':toast('已选择 Jellyfin');break}});
function bindLocal(){appScreen.querySelector('.scope')?.addEventListener('change',e=>{state.scope=e.target.value;render()});appScreen.querySelector('.search')?.addEventListener('input',e=>{state.query=e.target.value;appScreen.querySelector('#results').innerHTML=available().length?posters(available()):'<div class="notice">当前范围没有匹配的视频。</div>'});appScreen.querySelector('#connect-form')?.addEventListener('submit',e=>{e.preventDefault();state.scene='library';render();toast('演示连接成功 · 未发送任何网络请求')});let p=appScreen.querySelector('.player-visual'),x;if(p){p.addEventListener('pointerdown',e=>x=e.clientX);p.addEventListener('pointerup',e=>{if(x!==undefined&&Math.abs(e.clientX-x)>45)next(e.clientX<x?1:-1);x=undefined})}appScreen.querySelector('input[type=range]')?.addEventListener('input',e=>{let total=films[state.index].time.split(':').reduce((a,v)=>a*60+Number(v),0),t=Math.round(total*e.target.value/100);appScreen.querySelector('#elapsed').textContent=Math.floor(t/60).toString().padStart(2,'0')+':'+(t%60).toString().padStart(2,'0')})}
document.addEventListener('keydown',e=>{if(e.key==='Escape')appScreen.querySelector('.sheet-scrim')?.remove()});render();
